<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch, defineAsyncComponent, useId } from 'vue';
import { Camera, Crosshair, MapPin, Check, Send, X, TriangleAlert, Move } from '@lucide/vue';
import { api, native } from '../services/api'; import { capturePhoto, compressPhoto, currentLocation } from '../services/mediaService';
import type { Category, Hazard, GPS, Point, Severity } from '../types';
import HazardIcon from './HazardIcon.vue';
import municipality from '../config/municipality.json';
import ConfirmDialog from './ConfirmDialog.vue';
import Modal from './Modal.vue';
import { municipalSettings } from '../services/municipalSettings';
const HazardMap = defineAsyncComponent(() => import('./HazardMap.vue'));
const props = defineProps<{ categories: Category[]; demo: boolean }>(); const emit = defineEmits<{ created: [report?: Hazard]; close: [] }>(); const formId = useId();
const category = ref('');
watch(() => props.categories, items => { if (!items.some(item => item.id === category.value)) category.value = ''; }, { immediate: true }); const files = ref<File[]>([]); const previews = ref<string[]>([]); const fileInput = ref<HTMLInputElement>();
const gps = ref<GPS>(); const point = ref<Point>(); const showMap = ref(false); const adjusting = ref(false); const confirmed = ref(false); const locating = ref(false);
const title = ref(''); const description = ref(''); const barangay = ref(''); const address = ref(''); const severity = ref<Severity>('moderate');
const busy = ref(false); const processing = ref(false); const error = ref(''); const locationError = ref(''); const lat = ref<number | ''>(''); const lng = ref<number | ''>('');
const nearby = ref<{ id: string; reference_number: string; title: string; distance: number }[]>([]); const checked = ref(false); const forceNew = ref(false);
const outsideBasista = computed(() => point.value && (point.value.longitude < municipality.bounds[0]! || point.value.longitude > municipality.bounds[2]! || point.value.latitude < municipality.bounds[1]! || point.value.latitude > municipality.bounds[3]!));
const occurredAt = ref(''); const injuries = ref<'unknown' | 'yes' | 'no'>('unknown'); const peopleAffected = ref<number | ''>('');
const phone = computed(() => municipalSettings.value.hotlines[0]?.number || import.meta.env.VITE_EMERGENCY_PHONE); const pendingSubmit = ref(false);
const source = computed(() => !gps.value ? 'manual' : point.value && Math.abs(point.value.latitude - gps.value.latitude) < 0.000001 && Math.abs(point.value.longitude - gps.value.longitude) < 0.000001 ? 'gps' : 'gps_adjusted');
watch([point, category], () => { confirmed.value = false; checked.value = false; nearby.value = []; forceNew.value = false; });
watch(files, value => { previews.value.forEach(URL.revokeObjectURL); previews.value = value.map(URL.createObjectURL); });
onBeforeUnmount(() => previews.value.forEach(URL.revokeObjectURL));
function pick(p: Point) { point.value = p; lat.value = p.latitude; lng.value = p.longitude; }
function coordinates() { if (typeof lat.value === 'number' && typeof lng.value === 'number' && Math.abs(lat.value) <= 90 && Math.abs(lng.value) <= 180) pick({ latitude: lat.value, longitude: lng.value }); else { point.value = undefined; confirmed.value = false; } }
async function locate() { locating.value = true; locationError.value = ''; try { gps.value = await currentLocation(); pick({ latitude: gps.value.latitude, longitude: gps.value.longitude }); showMap.value = true; adjusting.value = false; } catch (e) { locationError.value = (e as Error).message; } finally { locating.value = false; } }
function manual() { showMap.value = true; adjusting.value = true; confirmed.value = false; }
async function addFiles(event: Event) { processing.value = true; error.value = ''; try { const selected = Array.from((event.target as HTMLInputElement).files || []).slice(0, 3 - files.value.length); const compressed = []; for (const file of selected) compressed.push(await compressPhoto(file)); files.value = [...files.value, ...compressed]; } catch (e) { error.value = (e as Error).message; } finally { processing.value = false; (event.target as HTMLInputElement).value = ''; } }
async function camera() { if (!native) return fileInput.value?.click(); processing.value = true; error.value = ''; try { files.value = [...files.value, await capturePhoto()].slice(0, 3); } catch (e) { error.value = (e as Error).message; } finally { processing.value = false; } }
async function submit() {
  error.value = ''; if (props.demo) { error.value = 'This is a read-only preview. Exit preview and sign in to send a real report.'; return; }
  if (!category.value) { error.value = 'Choose the type of incident. Piliin ang uri ng insidente.'; return; }
  if (!files.value.length) { error.value = 'Add at least one photo.'; return; }
  if (!point.value || !confirmed.value) { error.value = 'Choose and confirm the hazard location first.'; return; }
  busy.value = true;
  try { if (!checked.value) { nearby.value = await api(`/api/reports/nearby?category=${category.value}&latitude=${point.value.latitude}&longitude=${point.value.longitude}`); checked.value = true; if (nearby.value.length) return; } if (nearby.value.length && !forceNew.value) { error.value = 'Review the nearby hazards or choose to submit a separate report.'; return; } pendingSubmit.value = true; }
  catch (e) { error.value = (e as Error).message; } finally { busy.value = false; }
}
async function send() {
  if (!point.value || !confirmed.value) { pendingSubmit.value = false; return; }
  busy.value = true; error.value = '';
  try {
    const data = new FormData(); const values = { category_id: category.value, title: title.value, description: description.value, address: address.value, barangay: barangay.value, severity: severity.value, selected_latitude: point.value.latitude, selected_longitude: point.value.longitude, location_source: source.value, location_confirmed: '1', ...(gps.value ? { gps_latitude: gps.value.latitude, gps_longitude: gps.value.longitude, gps_accuracy: gps.value.accuracy } : {}) };
    if (occurredAt.value) data.set('occurred_at', new Date(occurredAt.value).toISOString());
    data.set('injuries', injuries.value);
    if (peopleAffected.value !== '') data.set('people_affected', String(peopleAffected.value));
    Object.entries(values).forEach(([key, value]) => data.set(key, String(value))); files.value.forEach(file => data.append('photos[]', file));
    const result = await api<{ data: Hazard }>('/api/reports', { method: 'POST', body: data }); pendingSubmit.value = false; emit('created', result.data);
  } catch (e) { pendingSubmit.value = false; error.value = (e as Error).message; } finally { busy.value = false; }
}
async function confirmDuplicate(id: string) { busy.value = true; error.value = ''; try { await api(`/api/reports/${id}/confirm`, { method: 'POST' }); emit('created'); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><Modal title="Report a hazard" wide @close="emit('close')"><form :id="formId" class="form-body report-form" @submit.prevent="submit">
  <div class="notice emergency"><TriangleAlert :size="22" /><p><strong>Is someone in immediate danger?</strong> Contact emergency services first. An app report does not request an emergency response.<a v-if="phone" :href="`tel:${phone}`">Call emergency services</a></p></div>
  <div v-if="demo" class="notice neutral">Preview mode · Explore the form. Reports will not be sent.</div>
  <div class="notice neutral privacy-notice"><p><strong>Your evidence stays private.</strong> Your report details, exact location and photos are available to you and authorized municipal administrators. Public updates use a separate summary reviewed by the municipality.</p></div>
  <fieldset><legend><span class="step">1</span> What happened?</legend><p class="filipino-help" lang="fil">Piliin ang uri ng insidente o panganib.</p><div class="category-grid"><button v-for="item in categories" :key="item.id" type="button" class="category-choice" :class="{ chosen: category === item.id }" :aria-pressed="category === item.id" @click="category = item.id"><HazardIcon :category="item.id" /><span>{{ item.name }}</span></button></div></fieldset>
  <fieldset><legend><span class="step">2</span> Add a photo</legend><p class="field-help">Stay at a safe distance. Up to 3 photos, automatically compressed below 1 MB each. Avoid faces, injuries and personal documents. Do not delay calling for help to take photos.</p><div class="photo-row"><div v-for="(url, index) in previews" :key="url" class="photo-preview"><img :src="url" :alt="`Hazard photo ${index + 1}`"><button type="button" :aria-label="`Remove photo ${index + 1}`" @click="files = files.filter((_, i) => i !== index)"><X :size="14" /></button><small>{{ Math.round(files[index]!.size / 1024) }} KB</small></div><button v-if="files.length < 3" type="button" class="photo-upload" :disabled="processing" @click="camera"><Camera :size="27" /><strong>{{ processing ? 'Compressing…' : 'Take or add photo' }}</strong></button><input ref="fileInput" class="visually-hidden" aria-label="Add hazard photos" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" multiple @change="addFiles"></div></fieldset>
  <fieldset><legend><span class="step">3</span> Where is the hazard?</legend><p class="filipino-help" lang="fil">Ilagay ang lokasyon ng insidente. Suriin ang pin bago kumpirmahin.</p><div class="location-options"><button type="button" class="location-choice" :disabled="locating" @click="locate"><Crosshair :size="23" /><strong>{{ locating ? 'Finding location…' : 'Use current location' }}</strong><small>Use your phone’s GPS</small></button><button type="button" class="location-choice" @click="manual"><MapPin :size="23" /><strong>Choose location on map</strong><small>Place the pin yourself</small></button></div><p v-if="locationError" class="form-error" role="alert">{{ locationError }}</p>
  <template v-if="showMap"><div class="location-heading"><span v-if="gps">GPS accuracy: <strong>±{{ Math.round(gps.accuracy) }} m</strong></span><span v-else>Manual location</span><span class="source-tag">{{ source.replace('_', ' ') }}</span></div><p v-if="gps && gps.accuracy > 100" class="notice emergency">GPS accuracy is low. Please check and adjust the hazard pin.</p><p class="field-help">{{ adjusting ? 'Tap the map or drag the green pin to the hazard. The blue dot is your original GPS.' : 'Is the green pin at the hazard? Confirm it below, or adjust the pin.' }}</p><div class="picker-map"><HazardMap style-selector :pin="point" :gps="gps" :editable="adjusting" @pick="pick" /></div><div class="form-grid coordinate-inputs"><label>Selected latitude<input v-model.number="lat" type="number" step="any" min="-90" max="90" :readonly="!adjusting" aria-label="Selected latitude" @input="coordinates"></label><label>Selected longitude<input v-model.number="lng" type="number" step="any" min="-180" max="180" :readonly="!adjusting" aria-label="Selected longitude" @input="coordinates"></label></div><p v-if="outsideBasista" class="notice emergency">The selected pin is outside Basista’s reference area. Check the pin and selected barangay before sending.</p><div class="location-actions"><button type="button" class="button secondary" @click="adjusting = true; confirmed = false"><Move :size="16" />Adjust pin</button><button type="button" class="button green" :disabled="!point" @click="confirmed = true; adjusting = false"><Check :size="17" />{{ confirmed ? 'Location confirmed' : 'Confirm location' }}</button></div></template>
  <div class="form-grid"><label>Barangay<select v-model="barangay" required aria-label="Barangay" aria-describedby="barangay-coverage"><option value="" disabled>Choose a Basista barangay</option><option v-for="name in municipality.barangays" :key="name" :value="name">{{ name }}</option></select><small id="barangay-coverage">Basista Municipal Hall covers these 13 barangays.</small></label><label>Street or landmark<input v-model="address" required minlength="3" maxlength="200" placeholder="Help responders find the location"></label></div></fieldset>
  <fieldset><legend><span class="step">4</span> A few details</legend><p class="filipino-help" lang="fil">Ilarawan ang nakita. Huwag ilagay ang pangalan o personal na detalye ng biktima.</p><div class="form-grid"><label>When did it happen? (optional)<input v-model="occurredAt" type="datetime-local"><span class="field-help">Use your phone?s local time. Leave blank if unknown.</span></label><label>Is anyone injured?<select v-model="injuries"><option value="unknown">Not sure / Hindi tiyak</option><option value="yes">Yes / May nasugatan</option><option value="no">None observed / Walang nakitang nasugatan</option></select></label><label>People affected (optional estimate)<input v-model.number="peopleAffected" type="number" min="0" max="1000000" step="1" inputmode="numeric" placeholder="Leave blank if unknown"></label></div><label>Report title<input v-model="title" required minlength="5" maxlength="120" placeholder="e.g. Fallen tree blocking Riverside Road"></label><label>Description<textarea v-model="description" required minlength="15" maxlength="2000" rows="3" placeholder="What can you see? Is access blocked or is anyone at risk?"></textarea></label><label>How serious does it appear?<select v-model="severity"><option value="low">Low — minor issue</option><option value="moderate">Moderate — needs attention</option><option value="high">High — significant risk</option><option value="critical">Critical — immediate danger</option></select></label></fieldset>
  <div v-if="nearby.length" class="duplicate-panel"><h3>Similar hazards nearby</h3><p>Is this the same incident? Confirm it to help avoid duplicate dispatches.</p><div v-for="item in nearby" :key="item.id" class="duplicate"><div><strong>{{ item.title }}</strong><small>{{ Math.round(item.distance) }} m away · {{ item.reference_number }}</small></div><button type="button" class="button secondary" :disabled="busy" @click="confirmDuplicate(item.id)">Same hazard</button></div><label class="checkbox-label"><input v-model="forceNew" type="checkbox">This is a different hazard; submit a new report.</label></div>
  </form><template #footer><p v-if="error" class="form-error" role="alert">{{ error }}</p><button type="submit" :form="formId" class="button primary full" :disabled="busy || processing"><Send :size="17" />{{ busy ? 'Sending…' : 'Submit hazard report' }}</button><p class="field-help center footer-hint">Keep yourself safe. An app report is not an emergency call. You can track a successfully submitted report in My reports.</p>
</template></Modal><ConfirmDialog v-if="pendingSubmit" title="Submit this hazard report?" message="Your exact location, description and photos will be shared privately with authorized municipal administrators for review. An app submission does not guarantee an emergency dispatch." :busy="busy" confirm-label="Submit report" @close="pendingSubmit = false" @confirm="send" /></template>
